import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateProductsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateProductsWorkflow(req.scope)
    .run({
      input: {
        products: [{
            id: "prod_123",
            title: "Shirts"
          },
          {
            id: "prod_321",
            variants: [{
              id: "variant_123",
              options: {
                Size: "S"
              }
            }]
          }
        ],
        additional_data: {
          erp_id: "erp_123"
        }
      }
    })

  res.send(result)
}

